let layers=[{name:'Layer 1',enabled:true,effect:state}],activeLayer=0;
try{const saved=JSON.parse(localStorage.getItem('ember-layers'));if(saved?.layers?.length&&saved.layers.length<=8){layers=saved.layers.map(l=>({...l,effect:EmberCatalog.normalize(l.effect),particles:[],budget:0,time:0}));state=layers[0].effect;}}catch{}
function stashLayer(){layers[activeLayer].effect=state;}
function renderLayers(){const host=$('#layers-list');host.replaceChildren();layers.forEach((layer,index)=>{const row=document.createElement('div');row.className='layer-row'+(index===activeLayer?' active':'');const enabled=document.createElement('input');enabled.type='checkbox';enabled.checked=layer.enabled;enabled.setAttribute('aria-label','Show '+layer.name);enabled.onchange=()=>{layer.enabled=enabled.checked;persist()};const select=document.createElement('button');select.textContent=layer.name+' · '+layer.effect.name;select.onclick=()=>{stashLayer();activeLayer=index;state=layer.effect;particles=layer.particles||[];sync();renderLayers()};const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove '+layer.name);remove.disabled=layers.length===1;remove.onclick=()=>{stashLayer();layers.splice(index,1);activeLayer=Math.min(activeLayer,layers.length-1);state=layers[activeLayer].effect;sync();renderLayers();persist()};row.append(enabled,select,remove);host.append(row);});$('#add-layer').disabled=layers.length>=8;document.querySelectorAll('.preset-add:not(.saved-preset-add)').forEach(button=>button.disabled=layers.length>=8);window.refreshSavedPresetCapacity?.();}
function saveLayers(){stashLayer();try{localStorage.setItem('ember-layers',JSON.stringify({layers:layers.map(({name,enabled,effect})=>({name,enabled,effect}))}));}catch{$('#saved').textContent='Recovery storage full — save project to keep changes';}}
const previousPersist=persist;persist=()=>{previousPersist();saveLayers();renderLayers()};
const previousSync=sync;sync=()=>{state=EmberCatalog.normalize(state);previousSync();for(const key of ['anime','animeSteps','animeOutline','trailLength','radiusVariation','emitScaleX','emitScaleY','emitScaleZ','spinVariation','directionRandom','spriteRotationRandom','motion','velocityYaw','velocityPitch','ringSpin','positionX','positionY','positionZ','shape','sprite','gravity','turbulence','endSize','endOpacity','bounce']){const input=$('#advanced-'+key);if(!input)continue;if(input.type==='checkbox')input.checked=state[key];else input.value=state[key];const output=$('#advanced-value-'+key);if(output)output.textContent=state[key];}renderMotionControls();renderLayers()};
restart=()=>{particles=[];elapsed=0;spawnBudget=0;for(const layer of layers)EmberAnimation.reset(layer);};
function addParticleLayer(effect,name){if(layers.length>=8){toast('Up to eight layers per effect');return;}stashLayer();const base=name;let suffix=2;while(layers.some(layer=>layer.name===name))name=base+' '+suffix++;layers.push({name,enabled:true,effect:EmberCatalog.normalize(JSON.parse(JSON.stringify(effect))),particles:[],budget:0,time:0});activeLayer=layers.length-1;state=layers[activeLayer].effect;particles=[];sync();persist();toast(name+' added — edit its particles in the controls');}
window.emberCanAddLayer=()=>layers.length<8;
window.emberAddPresetLayer=id=>{const preset=EmberCatalog.presets.find(p=>p.id===id);if(preset)addParticleLayer(preset,preset.name);};
$('#add-layer').onclick=()=>addParticleLayer(EmberCatalog.presets.find(p=>p.id==='custom'),'Layer '+(layers.length+1));
$('#duplicate-layer').onclick=()=>{if(layers.length>=8){toast('Up to eight layers per effect');return;}stashLayer();layers.push({name:layers[activeLayer].name+' copy',enabled:true,effect:JSON.parse(JSON.stringify(state)),particles:[],budget:0,time:0});activeLayer=layers.length-1;state=layers[activeLayer].effect;sync();restart();persist()};
for(const key of ['anime','animeSteps','animeOutline','trailLength','radiusVariation','emitScaleX','emitScaleY','emitScaleZ','spinVariation','directionRandom','spriteRotationRandom','motion','velocityYaw','velocityPitch','ringSpin','positionX','positionY','positionZ','shape','sprite','gravity','turbulence','endSize','endOpacity','bounce']){$('#advanced-'+key).oninput=e=>{if(['animeSteps','animeOutline','trailLength','radiusVariation','emitScaleX','emitScaleY','emitScaleZ','spinVariation','directionRandom','spriteRotationRandom','velocityYaw','velocityPitch','ringSpin'].includes(key)&&(!Number.isFinite(e.target.valueAsNumber)||e.target.valueAsNumber<+e.target.min||e.target.valueAsNumber>+e.target.max))return;if(key.startsWith('position')&&(!Number.isFinite(e.target.valueAsNumber)||Math.abs(e.target.valueAsNumber)>10000))return;state[key]=e.target.type==='checkbox'?e.target.checked:['shape','sprite','motion'].includes(key)?e.target.value:+e.target.value;const output=$('#advanced-value-'+key);if(output)output.textContent=state[key];if(key==='motion'&&state.motion==='orbit')state.shape='ring';if(key.startsWith('emitScale')||['directionRandom','spriteRotationRandom'].includes(key)||key.startsWith('position')||['radiusVariation','emitScaleX','emitScaleY','emitScaleZ','spinVariation','directionRandom','spriteRotationRandom','motion','velocityYaw','velocityPitch'].includes(key))window.resetSelectedLayer?.();if(key==='anime')renderMotionControls();if(key==='animeSteps'&&!Number.isInteger(state.animeSteps)){state.animeSteps=Math.round(state.animeSteps);sync();}if(key==='motion'||key==='shape')sync();persist()};}
$('#reset-position').onclick=()=>{state.positionX=0;state.positionY=0;state.positionZ=0;sync();window.resetSelectedLayer?.();persist()};
function updateLayers(dt){stashLayer();const output=[];for(const layer of layers){if(!layer.enabled)continue;output.push(...EmberAnimation.update(layer,dt,playing));}window.updateAnimationPlayhead?.();return output;}
window.emberProject=()=>{stashLayer();return ({format:'ember-vfx',version:2,name:$('#name').value.slice(0,100),effect:state,layers:layers.map(({name,enabled,effect})=>({name,enabled,effect}))});};
window.emberLoadProject=data=>{layers=(data.layers||[{name:'Layer 1',enabled:true,effect:data.effect}]).map(l=>({...l,effect:EmberCatalog.normalize(l.effect),particles:[],budget:0,time:0}));activeLayer=0;state=layers[0].effect;$('#name').value=data.name;sync();restart();persist()};
sync();

window.resetSelectedLayer=()=>{particles=[];const layer=layers[activeLayer];EmberAnimation.reset(layer);};

function renderMotionControls(){$('#advanced-animeSteps').disabled=$('#advanced-animeOutline').disabled=!state.anime;$('#advanced-trailLength').disabled=!state.trail;$('#velocity-angles').hidden=state.motion!=='aimed';$('#ring-spin-controls').hidden=state.motion!=='orbit';$('#advanced-shape').disabled=state.motion==='orbit';$('#advanced-directionRandom').disabled=state.motion==='orbit';$('#advanced-radiusVariation').disabled=state.motion!=='orbit'&&state.shape!=='ring';for(const key of ['gravity','turbulence','bounce'])$('#advanced-'+key).disabled=state.motion==='orbit';const speed=$('[data-key="speed"]');if(speed)speed.disabled=state.motion==='orbit';}
renderMotionControls();

$('#reset-stretch').onclick=()=>{state.emitScaleX=state.emitScaleY=state.emitScaleZ=1;sync();window.resetSelectedLayer?.();persist()};

$('#anime-all-layers').onclick=()=>{stashLayer();for(const layer of layers){layer.effect.anime=state.anime;layer.effect.animeSteps=state.animeSteps;layer.effect.animeOutline=state.animeOutline;}sync();persist();toast(state.anime?'Anime look applied to all layers':'Anime filter removed from all layers');};
